1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root { --cell: 28px; }
9	  * { box-sizing: border-box; }
10	  body {
11	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
12	    background: #14161c; color: #e8e8ee; font: 15px/1.4 system-ui, sans-serif;
13	  }
14	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
15	  .board {
16	    display: grid; grid-template-columns: repeat(10, var(--cell)); grid-template-rows: repeat(20, var(--cell));
17	    gap: 1px; background: #2a2d36; border: 2px solid #3a3e4a;
18	  }
19	  .cell { width: var(--cell); height: var(--cell); background: #1c1f27; }
20	  .side { display: flex; flex-direction: column; gap: 14px; min-width: 130px; }
21	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: #8a8fa0; }
22	  .stat .value { font-size: 22px; font-weight: 600; }
23	  .preview { display: grid; grid-template-columns: repeat(4, 18px); grid-template-rows: repeat(2, 18px); gap: 1px; margin-bottom: 8px; }
24	  .preview .mini { width: 18px; height: 18px; background: transparent; }
25	  .help { font-size: 12px; color: #8a8fa0; }
26	  .game-over { font-size: 18px; font-weight: 700; color: #ff6b6b; }
27	  .p-I { background: #00c8e0 !important; }
28	  .p-O { background: #f0d000 !important; }
29	  .p-T { background: #a040f0 !important; }
30	  .p-S { background: #30c050 !important; }
31	  .p-Z { background: #e03030 !important; }
32	  .p-J { background: #3060f0 !important; }
33	  .p-L { background: #f08c20 !important; }
34	</style>
35	</head>
36	<body>
37	<div class="game">
38	  <div class="board" data-testid="board" id="board"></div>
39	  <div class="side">
40	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
41	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
42	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
43	    <div class="stat"><div class="label">Next</div><div id="next" data-testid="next-piece"></div></div>
44	    <div class="game-over" data-testid="game-over" id="game-over" hidden>Game over</div>
45	    <div class="help">← → move<br>↑ or X rotate<br>↓ soft drop<br>Space hard drop</div>
46	  </div>
47	</div>
48	<script>
49	(function () {
50	  var ROWS = 20, COLS = 10, LETTERS = ["I", "O", "T", "S", "Z", "J", "L"];
51	
52	  // [REQ-001] spawn shapes as [row, col] on the board
53	  var SHAPES = {
54	    I: [[0, 3], [0, 4], [0, 5], [0, 6]],
55	    O: [[0, 4], [0, 5], [1, 4], [1, 5]],
56	    T: [[0, 4], [1, 3], [1, 4], [1, 5]],
57	    S: [[0, 4], [0, 5], [1, 3], [1, 4]],
58	    Z: [[0, 3], [0, 4], [1, 4], [1, 5]],
59	    J: [[0, 3], [1, 3], [1, 4], [1, 5]],
60	    L: [[0, 5], [1, 3], [1, 4], [1, 5]]
61	  };
62	
63	  // [REQ-002] rotation box per piece: size and spawn origin (top-left of the box on the board)
64	  var BOX = {
65	    I: { size: 4, origin: [-1, 3] },
66	    O: { size: 2, origin: [0, 4] },
67	    T: { size: 3, origin: [0, 3] }, S: { size: 3, origin: [0, 3] }, Z: { size: 3, origin: [0, 3] },
68	    J: { size: 3, origin: [0, 3] }, L: { size: 3, origin: [0, 3] }
69	  };
70	  var KICKS = [0, -1, 1, -2, 2];  // sideways shifts tried when a rotation does not fit
71	  var LOCK_TICKS = 2;             // [REQ-002] ticks unable to fall before a piece locks
72	  var MAX_LOCK_RESETS = 3;        // [REQ-002] lock delay restarts allowed per piece
73	  // [REQ-003] points per clear by rows at once, times level; clearing together always beats one at a time
74	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
75	  var SOFT_DROP_POINTS = 1, HARD_DROP_POINTS = 2;  // [REQ-003] per cell moved down by the player
76	  var PREVIEW_COUNT = 3;          // [REQ-004] upcoming pieces shown in the preview
77	
78	  var state = {
79	    board: [],      // board[row][col] = letter or null
80	    current: null,  // { type, cells: [[r,c],...], origin: [r,c], lockTicks, lockResets }
81	    upcoming: [],
82	    score: 0, level: 1, lines: 0,
83	    status: "running"
84	  };
85	  var timer = null;
86	
87	  var boardEl = document.getElementById("board");
88	  var cellEls = [];
89	  for (var r = 0; r < ROWS; r++) {
90	    cellEls.push([]);
91	    for (var c = 0; c < COLS; c++) {
92	      var el = document.createElement("div");
93	      el.className = "cell";
94	      el.setAttribute("data-testid", "cell");
95	      el.setAttribute("data-row", r);
96	      el.setAttribute("data-col", c);
97	      boardEl.appendChild(el);
98	      cellEls[r].push(el);
99	    }
100	  }
101	
102	  function emptyBoard() {
103	    var b = [];
104	    for (var r = 0; r < ROWS; r++) { b.push(new Array(COLS).fill(null)); }
105	    return b;
106	  }
107	
108	  function randomLetter() {
109	    return LETTERS[Math.floor(Math.random() * LETTERS.length)];
110	  }
111	
112	  function validLetters(queue) {
113	    return (Array.isArray(queue) ? queue : []).filter(function (l) { return SHAPES[l]; });
114	  }
115	
116	  // [REQ-004] keep enough upcoming pieces to fill the preview, padding with random ones
117	  function fillUpcoming() {
118	    while (state.upcoming.length < PREVIEW_COUNT) state.upcoming.push(randomLetter());
119	  }
120	
121	  // [REQ-001] take the next piece from the queue, falling back to random
122	  function takeNext() {
123	    var letter = state.upcoming.length ? state.upcoming.shift() : randomLetter();
124	    fillUpcoming();
125	    return letter;
126	  }
127	
128	  // [REQ-004] a new piece that does not fit where it spawns ends the game
129	  function spawn() {
130	    var type = takeNext();
131	    var cells = SHAPES[type].map(function (p) { return [p[0], p[1]]; });
132	    if (!fits(cells)) {
133	      state.current = null;
134	      state.status = "gameover";
135	      if (timer) { clearInterval(timer); timer = null; }
136	      return;
137	    }
138	    state.current = {
139	      type: type,
140	      cells: cells,
141	      origin: BOX[type].origin.slice(),
142	      lockTicks: 0, lockResets: 0
143	    };
144	  }
145	
146	  function fits(cells) {
147	    return cells.every(function (p) {
148	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && !state.board[p[0]][p[1]];
149	    });
150	  }
151	
152	  function canMove(dr, dc) {
153	    return fits(state.current.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; }));
154	  }
155	
156	  function tryMove(dr, dc) {
157	    if (!state.current || !canMove(dr, dc)) return false;
158	    var cur = state.current;
159	    cur.cells = cur.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; });
160	    cur.origin = [cur.origin[0] + dr, cur.origin[1] + dc];
161	    if (dr > 0) cur.lockTicks = 0;
162	    return true;
163	  }
164	
165	  // [REQ-002] rotate clockwise inside the piece's box; try sideways shifts; refuse if nothing fits
166	  function tryRotateCW() {
167	    var cur = state.current, n = BOX[cur.type].size, o = cur.origin;
168	    var turned = cur.cells.map(function (p) {
169	      var lr = p[0] - o[0], lc = p[1] - o[1];
170	      return [o[0] + lc, o[1] + n - 1 - lr];
171	    });
172	    // a rotation near the top edge is pushed down just enough to stay on the board
173	    var dr = Math.max(0, -Math.min.apply(null, turned.map(function (p) { return p[0]; })));
174	    for (var i = 0; i < KICKS.length; i++) {
175	      var dc = KICKS[i];
176	      var cand = turned.map(function (p) { return [p[0] + dr, p[1] + dc]; });
177	      if (fits(cand)) {
178	        cur.cells = cand;
179	        cur.origin = [o[0] + dr, o[1] + dc];
180	        return true;
181	      }
182	    }
183	    return false;
184	  }
185	
186	  // [REQ-002] [REQ-005] restart the lock delay, at most MAX_LOCK_RESETS times per piece
187	  function restartLockDelay() {
188	    var cur = state.current;
189	    if (cur.lockResets < MAX_LOCK_RESETS) { cur.lockResets++; cur.lockTicks = 0; }
190	  }
191	
192	  // [REQ-002] sideways move; while resting it restarts the lock delay
193	  function shift(dc) {
194	    var resting = !canMove(1, 0);
195	    if (tryMove(0, dc) && resting) restartLockDelay();
196	  }
197	
198	  // [REQ-003] [REQ-005] soft drop scores per cell; on a resting piece it restarts the lock delay like a sideways move
199	  function softDrop() {
200	    if (tryMove(1, 0)) state.score += SOFT_DROP_POINTS;
201	    else restartLockDelay();
202	  }
203	
204	  // [REQ-003] remove full rows, drop everything above, count lines and score the clear
205	  function clearLines() {
206	    var kept = state.board.filter(function (row) { return !row.every(Boolean); });
207	    var cleared = ROWS - kept.length;
208	    if (!cleared) return;
209	    while (kept.length < ROWS) kept.unshift(new Array(COLS).fill(null));
210	    state.board = kept;
211	    state.lines += cleared;
212	    state.score += CLEAR_POINTS[cleared] * state.level;
213	  }
214	
215	  // [REQ-001] [REQ-003] lock the falling piece, clear full rows and spawn the next one
216	  function lock() {
217	    var cur = state.current;
218	    cur.cells.forEach(function (p) {
219	      if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) state.board[p[0]][p[1]] = cur.type;
220	    });
221	    clearLines();
222	    spawn();
223	  }
224	
225	  // [REQ-001] [REQ-002] one gravity step: fall one row, or count one tick of lock delay
226	  function gravityStep() {
227	    if (state.status !== "running") return;
228	    if (!state.current) spawn();
229	    else if (!tryMove(1, 0) && ++state.current.lockTicks >= LOCK_TICKS) lock();
230	    render();
231	  }
232	
233	  // [REQ-001] [REQ-002] [REQ-003] player actions; hard drop locks at once, with no delay; drops score per cell
234	  function input(action) {
235	    if (state.status !== "running" || !state.current) return;
236	    if (action === "left") shift(-1);
237	    else if (action === "right") shift(1);
238	    else if (action === "rotateCW") tryRotateCW();
239	    else if (action === "softDrop") softDrop();
240	    else if (action === "hardDrop") {
241	      while (tryMove(1, 0)) state.score += HARD_DROP_POINTS;
242	      lock();
243	    }
244	    render();
245	  }
246	
247	  // [REQ-001] synchronous render from the real game state
248	  function render() {
249	    var drawn = state.board.map(function (row) { return row.slice(); });
250	    if (state.current) {
251	      state.current.cells.forEach(function (p) {
252	        if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) drawn[p[0]][p[1]] = state.current.type;
253	      });
254	    }
255	    for (var r = 0; r < ROWS; r++) {
256	      for (var c = 0; c < COLS; c++) {
257	        var el = cellEls[r][c], letter = drawn[r][c];
258	        el.className = letter ? "cell p-" + letter : "cell";
259	        el.setAttribute("data-filled", letter ? "true" : "false");
260	        el.setAttribute("data-piece", letter || "");
261	      }
262	    }
263	    document.getElementById("score").textContent = String(state.score);
264	    document.getElementById("level").textContent = String(state.level);
265	    document.getElementById("lines").textContent = String(state.lines);
266	    renderNext();
267	    document.getElementById("game-over").hidden = state.status !== "gameover";
268	  }
269	
270	  // [REQ-004] next three pieces, soonest first, coloured as on the board
271	  function renderNext() {
272	    var box = document.getElementById("next");
273	    box.innerHTML = "";
274	    state.upcoming.slice(0, PREVIEW_COUNT).forEach(function (type) {
275	      var grid = document.createElement("div");
276	      grid.className = "preview";
277	      grid.setAttribute("data-testid", "next-piece-item");
278	      grid.setAttribute("data-piece", type);
279	      var filled = {};
280	      SHAPES[type].forEach(function (p) { filled[p[0] + "," + (p[1] - 3)] = true; });
281	      for (var r = 0; r < 2; r++) {
282	        for (var c = 0; c < 4; c++) {
283	          var m = document.createElement("div");
284	          m.className = filled[r + "," + c] ? "mini p-" + type : "mini";
285	          grid.appendChild(m);
286	        }
287	      }
288	      box.appendChild(grid);
289	    });
290	  }
291	
292	  function startTimer() {
293	    if (timer) clearInterval(timer);
294	    timer = setInterval(gravityStep, 1000);
295	  }
296	
297	  // [REQ-001] start a fresh game, optionally with a fixed piece queue
298	  function newGame(queue) {
299	    state.board = emptyBoard();
300	    state.score = 0; state.level = 1; state.lines = 0;
301	    state.status = "running";
302	    state.upcoming = validLetters(queue);
303	    state.current = null;
304	    spawn();
305	    startTimer();
306	    render();
307	  }
308	
309	  // [REQ-001] test control surface
310	  window.__tetris = {
311	    newGame: newGame,
312	    setQueue: function (queue) {
313	      state.upcoming = validLetters(queue);
314	      fillUpcoming();
315	      render();
316	    },
317	    setBoard: function (rows) {
318	      var b = emptyBoard();
319	      for (var r = 0; r < ROWS; r++) {
320	        var line = (rows && rows[r]) || "";
321	        for (var c = 0; c < COLS; c++) {
322	          var ch = line.charAt(c);
323	          b[r][c] = SHAPES[ch] ? ch : null;
324	        }
325	      }
326	      state.board = b;
327	      render();
328	    },
329	    tick: function (n) {
330	      if (n === undefined) n = 1;
331	      for (var i = 0; i < n; i++) gravityStep();
332	    },
333	    input: input,
334	    getBoard: function () {
335	      return state.board.map(function (row) {
336	        return row.map(function (v) { return v || "."; }).join("");
337	      });
338	    },
339	    getState: function () {
340	      return {
341	        current: state.current
342	          ? {
343	              type: state.current.type,
344	              cells: state.current.cells.map(function (p) { return [p[0], p[1]]; }),
345	              lockTicks: state.current.lockTicks,
346	              lockResets: state.current.lockResets
347	            }
348	          : null,
349	        next: state.upcoming.slice(),
350	        score: state.score, level: state.level, lines: state.lines,
351	        status: state.status
352	      };
353	    }
354	  };
355	
356	  document.addEventListener("keydown", function (e) {
357	    var map = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", x: "rotateCW", X: "rotateCW", " ": "hardDrop", Spacebar: "hardDrop" };
358	    var action = map[e.key];
359	    if (!action) return;
360	    e.preventDefault();
361	    input(action);
362	  });
363	
364	  newGame();
365	})();
366	</script>
367	</body>
368	</html>
